INSERT INTO `t_knowledge_card` VALUES (682,'K_cfb040ebb1f14de7b22579034eef8fa9',8,'FACT','一、适用范围与核心内容','一、适用范围与核心内容\n\n采购金额不超过50000元由部门负责人审批；超过50000元由部门负责人及财务负责人共同审批。2026-01-01生效。','一、适用范围与核心内容\n\n采购金额不超过50000元由部门负责人审批；超过50000元由部门负责人及财务负责人共同审批。2026-01-01生效。',0.6800,'DRAFT','[]',1,'2026-10-17 09:59:26','2026-10-17 09:59:26');
INSERT INTO `t_knowledge_card` VALUES (683,'K_64117add6a204ae4b356c8cbb3330216',8,'FACT','二、执行规则与证据要点','二、执行规则与证据要点\n\n合同签署前须完成供应商资质审查；所有审批记录保留至少三年。','二、执行规则与证据要点\n\n合同签署前须完成供应商资质审查；所有审批记录保留至少三年。',0.6800,'DRAFT','[]',1,'2026-10-17 09:59:26','2026-10-17 09:59:26');
