INSERT INTO `t_knowledge_version` VALUES (2489,10,'CARD','K_0ed21567b47d4de981162f572622001b',1,'验证问题回答要求','验证问题要求概括模拟漏洞公告的关键要求并提供来源引用，关联相关实体、规则和证据，并说明冲突裁决方法。','请概括模拟漏洞公告_KB-2026-001的关键要求并提供来源引用。将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。如果文件内容与其他版本冲突，应该如何裁决？','DRAFT',1.0000,'CREATED','AI_EXTRACTION',NULL,'2026-10-17 10:59:22');
INSERT INTO `t_knowledge_version` VALUES (2505,10,'CARD','K_1355aec159a0418d86fff1e4aa62045c',1,'模拟漏洞修复与缓解方案 V1.0','模拟漏洞修复与缓解方案 V1.0\n\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\n\n文档编号: 文档类型；FIX-001: 修复方案\n文档编号: 数据分类；FIX-001: 05_漏洞库知识库\n文档编号: 密级；FIX-001: 内部\n文档编号: 发布日期；FIX-001: 2026-10-12\n文档编号: 数据属性；FIX-001: 合成测试数据，非真实企业资料','模拟漏洞修复与缓解方案 V1.0\n\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\n\n文档编号: 文档类型；FIX-001: 修复方案\n文档编号: 数据分类；FIX-001: 05_漏洞库知识库\n文档编号: 密级；FIX-001: 内部\n文档编号: 发布日期；FIX-001: 2026-10-12\n文档编号: 数据属性；FIX-001: 合成测试数据，非真实企业资料','DRAFT',0.6800,'CREATED','AI_EXTRACTION',NULL,'2026-10-17 10:59:23');
