INSERT INTO `t_knowledge_version` VALUES (2516,10,'CARD','K_222ed047022d4f03bf339b0a4f44e644',1,'一、适用范围与核心内容','一、适用范围与核心内容\n\n资产A-SEARCH-01运行atlas-search 2.4.0并启用debug端点；资产A-SEARCH-02运行2.4.1且禁用debug端点。','一、适用范围与核心内容\n\n资产A-SEARCH-01运行atlas-search 2.4.0并启用debug端点；资产A-SEARCH-02运行2.4.1且禁用debug端点。','DRAFT',0.6800,'CREATED','AI_EXTRACTION',NULL,'2026-10-17 10:59:26');
INSERT INTO `t_knowledge_version` VALUES (2507,10,'CARD','K_42d500c38b2d44349469bac484fcfee9',1,'二、执行规则与证据要点','二、执行规则与证据要点\n\n修复前备份配置，完成变更审批；升级后验证权限控制和查询可用性。','二、执行规则与证据要点\n\n修复前备份配置，完成变更审批；升级后验证权限控制和查询可用性。','DRAFT',0.6800,'CREATED','AI_EXTRACTION',NULL,'2026-10-17 10:59:23');
INSERT INTO `t_knowledge_version` VALUES (2486,10,'CARD','K_7d5291429e5a4f5b8bc10a9f234dced4',1,'受影响组件与条件','atlas-search 2.4.0 在启用 debug 端点且未配置访问控制的部署中，存在未经授权读取测试索引风险，严重性为高（模拟评估）。','影响范围：启用debug端点且未配置访问控制的部署。严重性：高（模拟评估）。','DRAFT',1.0000,'CREATED','AI_EXTRACTION',NULL,'2026-10-17 10:59:22');
