INSERT INTO `t_index_outbox` VALUES (2589,'506bd5c3-717d-4764-a9d3-d52a570d65d3','DOCUMENT_STANDARD:68:1',6,'DOCUMENT','KB:6:STANDARD:68','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"企业知识管理办法 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 43, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 22, \"content_hash\": \"9d2ef2c38e0140c4808caed5b93b4a54acd2d518f99706de30b6013784372804\", \"heading_path\": \"企业知识管理办法 V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"文档编号: 文档类型；KB-GEN-001: 制度\\n文档编号: 数据分类；KB-GEN-001: 01_综合知识库\\n文档编号: 密级；KB-GEN-001: 内部\\n文档编号: 发布日期；KB-GEN-001: 2026-10-12\\n文档编号: 数据属性；KB-GEN-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 198, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 45, \"chunk_type\": \"TABLE\", \"token_count\": 65, \"content_hash\": \"6325a661f11a6e2742d9d0a8712d63de7cb1a0b98b63f69339c0db43e4c30d44\", \"heading_path\": \"企业知识管理办法 V1.0\", \"overlap_prefix\": \"企业知识管理办法 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"一、适用范围与核心内容\\n\\n适用于全体员工。知识来源必须记录source_id、版本、密级、责任部门和生效日期。正式发布前须经知识审核员审批。\\n\\n二、执行规则与证据要点\\n\\n知识运营员负责清洗和提交；知识审核员负责证据核验和冲突裁决；系统管理员维护访问控制。\\n\\n三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\\n\\n四、验证问题\\n\\n请概括企业知识管理办法_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 496, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 200, \"chunk_type\": \"HEADING\", \"token_count\": 182, \"content_hash\": \"258356710b7dda461adb632c727dd330ec11aeadec47e88b707586bc3964f546\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"