INSERT INTO `t_index_outbox` VALUES (2590,'4480adb8-9fc7-42ca-869b-77c207c72499','DOCUMENT_STANDARD:69:1',6,'DOCUMENT','KB:6:STANDARD:69','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"项目星河交付说明 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 43, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 22, \"content_hash\": \"fb3cc5a6a6efe3b086c76441cda66852119bbc3c69562b8c4c3b73e2efa2644b\", \"heading_path\": \"项目星河交付说明 V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"文档编号: 文档类型；PRJ-XH-001: 项目\\n文档编号: 数据分类；PRJ-XH-001: 01_综合知识库\\n文档编号: 密级；PRJ-XH-001: 内部\\n文档编号: 发布日期；PRJ-XH-001: 2026-10-12\\n文档编号: 数据属性；PRJ-XH-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 198, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 45, \"chunk_type\": \"TABLE\", \"token_count\": 65, \"content_hash\": \"a60122eeab4fb385b0520b53f6c2e3a9ae490f31c0b4d415764920c3b9e9ec43\", \"heading_path\": \"项目星河交付说明 V1.0\", \"overlap_prefix\": \"项目星河交付说明 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"一、适用范围与核心内容\\n\\n星河项目建设企业搜索平台，交付范围包括知识采集、混合检索、问答溯源及权限审计。计划2026年11月完成试运行。\\n\\n二、执行规则与证据要点\\n\\n项目负责人周宁；技术负责人陈远；验收依据为检索准确率、引用覆盖率及越权访问测试。\\n\\n三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\\n\\n四、验证问题\\n\\n请概括项目星河交付说明_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 492, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 200, \"chunk_type\": \"HEADING\", \"token_count\": 180, \"content_hash\": \"3d402fabc960cdea9d74be4b3d761593230444ba81fbc041aec453bf8ce6fe58\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"据分类；