INSERT INTO `t_index_outbox` VALUES (2612,'0c27600c-99c6-43e3-bcd9-367b46df681b','CARD_CREATE:K_3f9d5d10c5ba44549570006c4b80b5c5:1',6,'CARD','KB:6:CARD:K_3f9d5d10c5ba44549570006c4b80b5c5','KNOWLEDGE_OBJECT_UPSERT',1,'/ai/index/knowledge','{\"cards\": [{\"type\": \"PROCEDURE\", \"title\": \"一、适用范围与核心内容\", \"status\": \"DRAFT\", \"content\": \"一、适用范围与核心内容\\n\\n适用于全体员工。知识来源必须记录source_id、版本、密级、责任部门和生效日期。正式发布前须经知识审核员审批。\\n\\n二、执行规则与证据要点\\n\\n知识运营员负责清洗和提交；知识审核员负责证据核验和冲突裁决；系统管理员维护访问控制。\\n\\n三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\\n\\n四、验证问题\\n\\n请概括企业知识管理办法_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"summary\": \"一、适用范围与核心内容\\n\\n适用于全体员工。知识来源必须记录source_id、版本、密级、责任部门和生效日期。正式发布前须经知识审核员审批。\\n\\n二、执行规则与证据要点\\n\\n知识运营员负责清洗和提交；知识审核员负责证据核验和冲突裁决；系统管理员维护访问控制。\\n\\n三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\\n\\n四、验证问题\\n\\n请概括企业知识管理办法_V1.0的关键要求并提供来源引用\", \"confidence\": 0.68, \"updated_at\": \"2026-10-17 09:14:35\", \"entity_codes\": [\"V1.0\", \"一、适用范围与核心内容\", \"source_id\", \"知识来源\", \"引用时\"], \"evidence_ids\": [\"EVD_a58970892cc24aaba2d5071571fb9273\"], \"evidence_code\": \"EVD_925987198c26420d9a5f96c1a6a492a0\", \"evidence_hash\": \"9d2ef2c38e0140c4808caed5b93b4a54acd2d518f99706de30b6013784372804\", \"evidence_count\": 3, \"knowledge_code\": \"K_3f9d5d10c5ba44549570006c4b80b5c5\", \"authority_score\": 0.8, \"permission_tags\": \"[]\"}], \"claims\": [], \"eventId\": \"0c27600c-99c6-43e3-bcd9-367b46df681b\", \"entities\": null, \"relations\": null, \"indexVersion\": 1, \"knowledgeBaseId\": 6}','SUCCEEDED',1,8,'2026-10-17 09:14:35',NULL,NULL,NULL,'{\"graph\": {\"provider\": \"neo4j\", \"available\": true, \"edgesCreated\": 0, \"nodesCreated\": 1}, \"total\": 27, \"indexed\": 1, \"external\": {\"milvus\": {\"indexed\": 1, \"provider\": \"milvus\"}, \"elasticsearch\": {\"indexed\": 1, \"provider\": \"elasticsearch\"}}, \"graphView\": 41}','2026-10-17 09:14:35','2026-10