INSERT INTO `t_index_outbox` VALUES (2628,'1ab667c2-8b25-408f-8278-5889524e5fad','DOCUMENT_STANDARD:72:1',7,'DOCUMENT','KB:7:STANDARD:72','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"检索服务变更记录 20261008\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；OPS-CHG-001: 变更\\n文档编号: 数据分类；OPS-CHG-001: 02_运维知识库\\n文档编号: 密级；OPS-CHG-001: 内部\\n文档编号: 发布日期；OPS-CHG-001: 2026-10-12\\n文档编号: 数据属性；OPS-CHG-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 207, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 90, \"content_hash\": \"e1ee6cd273b55b588fcc4a0496d4efda7687045b8d68248432e7f555a406cb63\", \"heading_path\": \"检索服务变更记录 20261008\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n2026-10-08模拟变更：检索服务从版本1.3.0升级至1.3.1，调整重排超时阈值，未更改知识库ACL策略。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 279, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 209, \"chunk_type\": \"HEADING\", \"token_count\": 36, \"content_hash\": \"ccee0528c434948c51c52fa8d6c904085223c46e836c01cc5fec3f3cb67c8f90\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n审批人运维主管李卓；回滚条件：5分钟错误率超过2%或P95延迟超过3秒。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 330, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 281, \"chunk_type\": \"HEADING\", \"token_count\": 28, \"content_hash\": \"e40a59b5f2d40af01d2e9c8ac74a7fbf205e3a4e88727d83d6d65402c65974fa\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 405, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 332, \"chunk_type\": \"HEADING\", \"token_count\": 47, \"content_hash\": \"cf48e6d73cf9b3cb3b4965927d487a4a8292ac58b3c2f976e6187a25b6987d9b\", \"heading_path\": \"三、数据治理与引用要求\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"四、验证问题\\n\\n请概括检索服务变更记录_20261008的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 503, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 407, \"chunk_type\": \"HEADING\", \"token_count\": 57, \"content_hash\": \"498fa0e0a3dcaf7218969f31a290e98c85a35738bdc93fdfda1a780abf3eeb7d\", \"heading_path\": \"四、验证问题\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}], \"eventId\": \"1ab667c2-8b25-408f-8278-5889524e5fad\", \"sourceId\": 72, \"standard\": {\"stats\": {\"chars\": 503, \"units\": 5, \"blocks\": 13, \"tables\": 1, \"tokens\": 258, \"sections\": 5, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"STRUCTURE\", \"chunkSize\": 700, \"parentChild\": true, \"chunkOverlap\": 90, \"minChunkSize\": 100, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"STRUCTURE\"}, \"title\": \"检索服务变更记录 20261008\", \"doc_id\": \"d58dc8a0289edaa436ef90e5378afbbf\", \"sha256\": \"1697bd76513f3e4a7ec07a14b6b79476933e45c3afa18c36751f7cb0b5754fee\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"DOCX\"}, \"sourceUri\": \"upload://03_检索服务变更记录_20261008.docx\", \"documentId\": 72, \"sourceName\": \"03_检索服务变更记录_20261008.docx\", \"indexVersion\": 1, \"permissionTags\": \"[]\", \"knowledgeBaseId\": 7}','SUCCEEDED',1,8,'2026-10-17 09:28:54',NULL,NULL,NULL,'{\"units\": 5, \"documentId\": 72, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 5}, \"knowledgeBaseId\": 7}','2026-10-17 09:28:54','2026-10-17 09:28:56','2026-10-17 09:28:56');
