INSERT INTO `t_index_outbox` VALUES (2630,'d3207f47-7398-49b9-92ba-bc47a1e3bdff','DOCUMENT_STANDARD:73:1',7,'DOCUMENT','KB:7:STANDARD:73','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"数据库连接池耗尽故障手册 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；OPS-DB-001: 故障手册\\n文档编号: 数据分类；OPS-DB-001: 02_运维知识库\\n文档编号: 密级；OPS-DB-001: 内部\\n文档编号: 发布日期；OPS-DB-001: 2026-10-12\\n文档编号: 数据属性；OPS-DB-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 204, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 92, \"content_hash\": \"7b69ae200f359d6e46a2fb0b6066b29289bbfe1496a229579952e86d73ac8d9a\", \"heading_path\": \"数据库连接池耗尽故障手册 V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n现象：接口延迟增加，连接池active达到上限，等待线程持续增长。先检查慢SQL、未释放连接和连接池配置。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 272, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 206, \"chunk_type\": \"HEADING\", \"token_count\": 38, \"content_hash\": \"62029a21971dcdcdb36ee0d96e0b93786179519b24d680193ecbb1d9651dc790\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n步骤：1.采集监控与日志；2.检查数据库活跃连接；3.隔离异常请求；4.必要时经审批调整连接池；5.记录恢复时间。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 344, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 274, \"chunk_type\": \"HEADING\", \"token_count\": 40, \"content_hash\": \"0b1f59cac0880cee48122df64343a9e9d96feac6e25efd4ac1bcb58e6a56fdd7\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 419, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 346, \"chunk_type\": \"HEADING\", \"token_count\": 47, \"content_hash\": \"cf48e6d73cf9b3cb3b4965927d487a4a8292ac58b3c2f976e6187a25b6987d9b\", \"heading_path\": \"三、数据治理与引用要求\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"四、验证问题\\n\\n请概括数据库连接池耗尽故障手册_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 517, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 421, \"chunk_type\": \"HEADING\", \"token_count\": 59, \"content_hash\": \"8229f13710993808dee0f7f8eaf2033fbe077f5c3741bd4b67d4985301a3a4bb\", \"heading_path\": \"四、验证问题\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}], \"eventId\": \"d3207f47-7398-49b9-92ba-bc47a1e3bdff\", \"sourceId\": 73, \"standard\": {\"stats\": {\"chars\": 517, \"units\": 5, \"blocks\": 13, \"tables\": 1, \"tokens\": 276, \"sections\": 5, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"STRUCTURE\", \"chunkSize\": 700, \"parentChild\": true, \"chunkOverlap\": 90, \"minChunkSize\": 100, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"STRUCTURE\"}, \"title\": \"数据库连接池耗尽故障手册 V1.0\", \"doc_id\": \"16f8faf86289a765189c6f685b50db97\", \"sha256\": \"bb17d0df682c4218b797a3dd1bd2eab5dd839ba753d822a46e94a4ada428a03c\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"DOCX\"}, \"sourceUri\": \"upload://01_数据库连接池耗尽故障手册_V1.0.docx\", \"documentId\": 73, \"sourceName\": \"01_数据库连接池耗尽故障手册_V1.0.docx\", \"indexVersion\": 1, \"permissionTags\": \"[]\", \"knowledgeBaseId\": 7}','SUCCEEDED',1,8,'2026-10-17 09:28:54',NULL,NULL,NULL,'{\"units\": 5, \"documentId\": 73, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 5}, \"knowledgeBaseId\": 7}','2026-10-17 09:28:54','2026-10-17 09:28:57','2026-10-17 09:28:57');
