INSERT INTO `t_index_outbox` VALUES (2632,'bf4295c1-875d-40fa-ad50-6f1216b2bd00','DOCUMENT_STANDARD:74:1',7,'DOCUMENT','KB:7:STANDARD:74','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"生产系统巡检规程 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；OPS-INS-001: 巡检\\n文档编号: 数据分类；OPS-INS-001: 02_运维知识库\\n文档编号: 密级；OPS-INS-001: 内部\\n文档编号: 发布日期；OPS-INS-001: 2026-10-12\\n文档编号: 数据属性；OPS-INS-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 203, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 89, \"content_hash\": \"b183ecf85f2ffdbd7a18d59c6431323c14203fe398ae14db498b56366a6df387\", \"heading_path\": \"生产系统巡检规程 V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n每日09:00检查CPU、内存、磁盘、数据库连接、索引任务积压和证书到期日。磁盘使用率超过85%触发预警。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 271, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 205, \"chunk_type\": \"HEADING\", \"token_count\": 37, \"content_hash\": \"fe4df3b26ceff2591675ca8367ad0a824864e52612af6e6718498068d7159c0f\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n值班工程师记录巡检结果；连续两次异常升级给运维主管。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 312, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 273, \"chunk_type\": \"HEADING\", \"token_count\": 25, \"content_hash\": \"82aba1ad3c4fd040975932a66400abcfaf16b99091bd82a90216e3442294b507\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 387, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 314, \"chunk_type\": \"HEADING\", \"token_count\": 47, \"content_hash\": \"cf48e6d73cf9b3cb3b4965927d487a4a8292ac58b3c2f976e6187a25b6987d9b\", \"heading_path\": \"三、数据治理与引用要求\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"四、验证问题\\n\\n请概括生产系统巡检规程_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 481, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 389, \"chunk_type\": \"HEADING\", \"token_count\": 56, \"content_hash\": \"d48985570a5deda9ee8ae238d6d4c901ea01cd157f3f9611445ddea640e1e927\", \"heading_path\": \"四、验证问题\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}], \"eventId\": \"bf4295c1-875d-40fa-ad50-6f1216b2bd00\", \"sourceId\": 74, \"standard\": {\"stats\": {\"chars\": 481, \"units\": 5, \"blocks\": 13, \"tables\": 1, \"tokens\": 254, \"sections\": 5, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"STRUCTURE\", \"chunkSize\": 700, \"parentChild\": true, \"chunkOverlap\": 90, \"minChunkSize\": 100, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"STRUCTURE\"}, \"title\": \"生产系统巡检规程 V1.0\", \"doc_id\": \"b06825286811c6c6073fabe0a9d6860b\", \"sha256\": \"1f3cca3f76ec6875df88a4aa3dbd9ec2fa30e7667b5bf6e663608178b0265e99\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"DOCX\"}, \"sourceUri\": \"upload://02_生产系统巡检规程_V1.0.docx\", \"documentId\": 74, \"sourceName\": \"02_生产系统巡检规程_V1.0.docx\", \"indexVersion\": 1, \"permissionTags\": \"[]\", \"knowledgeBaseId\": 7}','SUCCEEDED',1,8,'2026-10-17 09:28:54',NULL,NULL,NULL,'{\"units\": 5, \"documentId\": 74, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 5}, \"knowledgeBaseId\": 7}','2026-10-17 09:28:54','2026-10-17 09:28:58','2026-10-17 09:28:58');
