INSERT INTO `t_index_outbox` VALUES (2635,'fb6268a5-e0e6-4f04-8525-a3a50b8bcba6','DOCUMENT_STANDARD:75:1',7,'DOCUMENT','KB:7:STANDARD:75','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"索引积压告警处置SOP V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；OPS-ALERT-001: SOP\\n文档编号: 数据分类；OPS-ALERT-001: 02_运维知识库\\n文档编号: 密级；OPS-ALERT-001: 内部\\n文档编号: 发布日期；OPS-ALERT-001: 2026-10-12\\n文档编号: 数据属性；OPS-ALERT-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 217, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 92, \"content_hash\": \"4615bfd103d80ff6a11103d98454c6bf9afea7997327ddab23211a45e05fa745\", \"heading_path\": \"索引积压告警处置SOP V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n当outbox积压超过5000条且持续15分钟时告警。检查消费者状态、失败重试和死信队列。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 277, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 219, \"chunk_type\": \"HEADING\", \"token_count\": 32, \"content_hash\": \"fec67b183215453c89d5b0e609dbe77d95dbf99eff12917263a374fb6ff96db9\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n禁止直接删除未消费事件；恢复后比对高水位与索引快照，确认无遗漏。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 324, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 279, \"chunk_type\": \"HEADING\", \"token_count\": 29, \"content_hash\": \"39fc6fe81c7086c0c536c1d8177a3d95578ce84f7316633fe7938cba6fcf3165\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 399, \"page_end\": null, \"strategy\": \