INSERT INTO `t_index_outbox` VALUES (2637,'86a179d2-2932-4ce7-a83a-82ca85fec1bb','CARD_CREATE:K_16c7cd9054154dd3985baa941a484c28:1',7,'CARD','KB:7:CARD:K_16c7cd9054154dd3985baa941a484c28','KNOWLEDGE_OBJECT_UPSERT',1,'/ai/index/knowledge','{\"cards\": [{\"type\": \"FACT\", \"title\": \"一、适用范围与核心内容\", \"status\": \"DRAFT\", \"content\": \"一、适用范围与核心内容\\n\\n现象：接口延迟增加，连接池active达到上限，等待线程持续增长。先检查慢SQL、未释放连接和连接池配置。\", \"summary\": \"一、适用范围与核心内容\\n\\n现象：接口延迟增加，连接池active达到上限，等待线程持续增长。先检查慢SQL、未释放连接和连接池配置。\", \"confidence\": 0.68, \"updated_at\": \"2026-10-17 09:30:00\", \"entity_codes\": [\"一、适用范围与核心内容\", \"active\", \"SQL\"], \"evidence_ids\": [\"EVD_c34a094c948a41ad9577e901fcd3a8c8\"], \"evidence_code\": \"EVD_18c5c0cd89994e959993840ce59376e0\", \"evidence_hash\": \"7b69ae200f359d6e46a2fb0b6066b29289bbfe1496a229579952e86d73ac8d9a\", \"evidence_count\": 5, \"knowledge_code\": \"K_16c7cd9054154dd3985baa941a484c28\", \"authority_score\": 0.8, \"permission_tags\": \"[]\"}], \"claims\": [], \"eventId\": \"86a179d2-2932-4ce7-a83a-82ca85fec1bb\", \"entities\": null, \"relations\": null, \"indexVersion\": 1, \"knowledgeBaseId\": 7}','SUCCEEDED',1,8,'2026-10-17 09:30:00',NULL,NULL,NULL,'{\"graph\": {\"provider\": \"neo4j\", \"available\": true, \"edgesCreated\": 0, \"nodesCreated\": 1}, \"total\": 50, \"indexed\": 1, \"external\": {\"milvus\": {\"indexed\": 1, \"provider\": \"milvus\"}, \"elasticsearch\": {\"indexed\": 1, \"provider\": \"elasticsearch\"}}, \"graphView\": 64}','2026-10-17 09:30:00','2026-10-17 09:30:03','2026-10-17 09:30:03');
