INSERT INTO `t_index_outbox` VALUES (2650,'9d42fb54-88ad-4dbd-98ed-2cd7e2b1a00c','DOCUMENT_STANDARD:76:1',8,'DOCUMENT','KB:8:STANDARD:76','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"供应商服务合同示范条款 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；CONTRACT-001: 合同条款\\n文档编号: 数据分类；CONTRACT-001: 03_制度条款知识库\\n文档编号: 密级；CONTRACT-001: 内部\\n文档编号: 发布日期；CONTRACT-001: 2026-10-12\\n文档编号: 数据属性；CONTRACT-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 215, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 96, \"content_hash\": \"414b9b89005bc44add8ba3cdf10215019d6b8bc8e065d758a4b3e25abf30780d\", \"heading_path\": \"供应商服务合同示范条款 V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n供应商应在收到故障通知后4小时内响应，重大故障应在24小时内提交临时恢复方案。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 269, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 217, \"chunk_type\": \"HEADING\", \"token_count\": 33, \"content_hash\": \"5525408099fa0d4d5b9561fcbcf9d0d9e0c0dccd3275a6f9c77bdd7eb742b798\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n保密义务在合同终止后持续两年；违约责任依合同约定执行。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 311, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 271, \"chunk_type\": \"HEADING\", \"token_count\": 26, \"content_hash\": \"289221d0df5291ebed1aed6f0b3be2ed1716490a6e2137e191f3e3a5cdb9925d\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 386, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 313, \"chunk_type\": \"HEADING\", \"token_count\": 47, \"content_hash\": \"cf48e6d73cf9b3cb3b4965927d487a4a8292ac58b3c2f976e6187a25b6987d9b\", \"heading_path\": \"三、数据治理与引用要求\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"四、验证问题\\n\\n请概括供应商服务合同示范条款_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 483, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 388, \"chunk_type\": \"HEADING\", \"token_count\": 58, \"content_hash\": \"3f0c0e21c8e9e2e1601fe5b5082cbb3529bcd2cc6a7b05246ac68a5a30981131\", \"heading_path\": \"四、验证问题\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}], \"eventId\": \"9d42fb54-88ad-4dbd-98ed-2cd7e2b1a00c\", \"sourceId\": 76, \"standard\": {\"stats\": {\"chars\": 483, \"units\": 5, \"blocks\": 13, \"tables\": 1, \"tokens\": 260, \"sections\": 5, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"STRUCTURE\", \"chunkSize\": 1100, \"parentChild\": true, \"chunkOverlap\": 150, \"minChunkSize\": 120, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"STRUCTURE\"}, \"title\": \"供应商服务合同示范条款 V1.0\", \"doc_id\": \"007fd50299e874075c022292d53957e3\", \"sha256\": \"fd76d58a6a7b90bf0fcac4ec2a06c5872e929e8b8eb6ecc88be31d0f5e29fc12\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"DOCX\"}, \"sourceUri\": \"upload://03_供应商服务合同示范条款_V1.0.docx\", \"documentId\": 76, \"sourceName\": \"03_供应商服务合同示范条款_V1.0.docx\", \"indexVersion\": 1, \"permissionTags\": \"[]\", \"knowledgeBaseId\": 8}','SUCCEEDED',1,8,'2026-10-17 09:58:54',NULL,NULL,NULL,'{\"units\": 5, \"documentId\": 76, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 5}, \"knowledgeBaseId\": 8}','2026-10-17 09:58:54','2026-10-17 09:58:55','2026-10-17 09:58:55');
