INSERT INTO `t_index_outbox` VALUES (2652,'85e10f52-b241-4ea2-95c7-ac9b50000f1b','DOCUMENT_STANDARD:77:1',8,'DOCUMENT','KB:8:STANDARD:77','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"采购审批管理制度 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；POL-PROC-001: 制度\\n文档编号: 数据分类；POL-PROC-001: 03_制度条款知识库\\n文档编号: 密级；POL-PROC-001: 内部\\n文档编号: 发布日期；POL-PROC-001: 2026-10-12\\n文档编号: 数据属性；POL-PROC-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 210, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 92, \"content_hash\": \"3131af1f0214bf366c90a770388ba545d11976bf7d78d887519fb18696e0b50c\", \"heading_path\": \"采购审批管理制度 V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n采购金额不超过50000元由部门负责人审批；超过50000元由部门负责人及财务负责人共同审批。2026-01-01生效。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 285, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 212, \"chunk_type\": \"HEADING\", \"token_count\": 39, \"content_hash\": \"c5a2268bdf25ec98bb53d22b2020b6c16520ba66d2526b6abe9cd288e197ac9c\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n合同签署前须完成供应商资质审查；所有审批记录保留至少三年。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 329, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 287, \"chunk_type\": \"HEADING\", \"token_count\": 27, \"content_hash\": \"b5aafe989070b64382928e40dd0fa1c38286291d5cc8f0baaeff1cf97c8c40f7\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 404, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 331, \"chunk_type\": \"HEADING\", \"token_count\": 47, \"content_hash\": \"cf48e6d73cf9b3cb3b4965927d487a4a8292ac58b3c2f976e6187a25b6987d9b\", \"heading_path\": \"三、数据治理与引用要求\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"四、验证问题\\n\\n请概括采购审批管理制度_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 498, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 406, \"chunk_type\": \"HEADING\", \"token_count\": 56, \"content_hash\": \"d845975aa0cf66b40c87fa161e4345b523738e283f7a40fc73295bd5694f0d41\", \"heading_path\": \"四、验证问题\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}], \"eventId\": \"85e10f52-b241-4ea2-95c7-ac9b50000f1b\", \"sourceId\": 77, \"standard\": {\"stats\": {\"chars\": 498, \"units\": 5, \"blocks\": 13, \"tables\": 1, \"tokens\": 261, \"sections\": 5, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"STRUCTURE\", \"chunkSize\": 1100, \"parentChild\": true, \"chunkOverlap\": 150, \"minChunkSize\": 120, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"STRUCTURE\"}, \"title\": \"采购审批管理制度 V1.0\", \"doc_id\": \"8574899a2bebbc87873bb94e09e47157\", \"sha256\": \"4d5542ff4cbb719c7a0fc22891730d1b54f1eebc4a2cbe6285191071a5f5ad0c\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"DOCX\"}, \"sourceUri\": \"upload://01_采购审批管理制度_V1.0.docx\", \"documentId\": 77, \"sourceName\": \"01_采购审批管理制度_V1.0.docx\", \"indexVersion\": 1, \"permissionTags\": \"[]\", \"knowledgeBaseId\": 8}','SUCCEEDED',1,8,'2026-10-17 09:58:54',NULL,NULL,NULL,'{\"units\": 5, \"documentId\": 77, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 5}, \"knowledgeBaseId\": 8}','2026-10-17 09:58:54','2026-10-17 09:58:56','2026-10-17 09:58:56');
