INSERT INTO `t_index_outbox` VALUES (2666,'c159476c-3106-4c23-99da-b4b94e4192ce','DOCUMENT_STANDARD:79:1',8,'DOCUMENT','KB:8:STANDARD:79','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"制度冲突裁决记录 20260905\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；JUDGE-001: 裁决记录\\n文档编号: 数据分类；JUDGE-001: 03_制度条款知识库\\n文档编号: 密级；JUDGE-001: 内部\\n文档编号: 发布日期；JUDGE-001: 2026-10-12\\n文档编号: 数据属性；JUDGE-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 201, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 91, \"content_hash\": \"4169e3807a9f7da879b263cc2e614273a3a272e58727a57772d9b10feb11a95f\", \"heading_path\": \"制度冲突裁决记录 20260905\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n冲突：采购审批门槛在V1.0为50000元，在V2.0为30000元。裁决：2026-09-01及之后发生的采购适用V2.0。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 279, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 203, \"chunk_type\": \"HEADING\", \"token_count\": 35, \"content_hash\": \"7b8e00ae3a9de31529a8f6ccc56ee18a1c31c76f25dfc1354803a724875455fb\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n裁决依据：新版生效日期及明确替代条款；历史采购按发生时有效版本核验。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 328, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 281, \"chunk_type\": \"HEADING\", \"token_count\": 30, \"content_hash\": \"09708705632a8fbedb5aa3a8b13ebcd9d2a9973fc608f2d29d66a2e6cc67e31a\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 403, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 330, \"chunk_type\": \"HEADING\", \"token_count\": 47, \"content_hash\": \"cf48e6d73cf9b3cb3b4965927d487a4a8292ac58b3c2f976e6187a25b6987d9b\", \"heading_path\": \"三、数据治理与引用要求\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"四、验证问题\\n\\n请概括制度冲突裁决记录_20260905的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 501, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 405, \"chunk_type\": \"HEADING\", \"token_count\": 57, \"content_hash\": \"78e1fd628137f16dd88db70f9119b0ae97a33a19fa03c29c953a83288f96893d\", \"heading_path\": \"四、验证问题\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}], \"eventId\": \"c159476c-3106-4c23-99da-b4b94e4192ce\", \"sourceId\": 79, \"standard\": {\"stats\": {\"chars\": 501, \"units\": 5, \"blocks\": 13, \"tables\": 1, \"tokens\": 260, \"sections\": 5, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"STRUCTURE\", \"chunkSize\": 1100, \"parentChild\": true, \"chunkOverlap\": 150, \"minChunkSize\": 120, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"STRUCTURE\"}, \"title\": \"制度冲突裁决记录 20260905\", \"doc_id\": \"bb6a4e23412d96a321cb8a2c0880e30b\", \"sha256\": \"f26f49cf255d3ad3af14969c7937783b707ba4d0048c21c9ea1717e12730ac34\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"DOCX\"}, \"sourceUri\": \"upload://04_制度冲突裁决记录_20260905.docx\", \"documentId\": 79, \"sourceName\": \"04_制度冲突裁决记录_20260905.docx\", \"indexVersion\": 1, \"permissionTags\": \"[]\", \"knowledgeBaseId\": 8}','SUCCEEDED',1,8,'2026-10-17 09:59:25',NULL,NULL,NULL,'{\"units\": 5, \"documentId\": 79, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 5}, \"knowledgeBaseId\": 8}','2026-10-17 09:59:25','2026-10-17 09:59:36','2026-10-17 09:59:36');
