INSERT INTO `t_index_outbox` VALUES (2678,'090013b3-85ae-4807-a887-bcdfb4f5cc88','DOCUMENT_STANDARD:80:1',9,'DOCUMENT','KB:9:STANDARD:80','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"企业组织架构 2026Q4\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 43, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 22, \"content_hash\": \"d3d8388ba36df4294e15cf0931f0bb605c617f633ef710547213a481b6a446a5\", \"heading_path\": \"企业组织架构 2026Q4\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"文档编号: 文档类型；ORG-001: 组织档案\\n文档编号: 数据分类；ORG-001: 04_公司业务人员关系知识库\\n文档编号: 密级；ORG-001: 内部受控\\n文档编号: 发布日期；ORG-001: 2026-10-12\\n文档编号: 数据属性；ORG-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 193, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 45, \"chunk_type\": \"TABLE\", \"token_count\": 68, \"content_hash\": \"18a844722b04df2aca03abedc35d66eb529bc5bdfe1fbde8403d33316ac3ea83\", \"heading_path\": \"企业组织架构 2026Q4\", \"overlap_prefix\": \"企业组织架构 2026Q4\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"一、适用范围与核心内容\\n\\n星云科技（虚构）设产品部、研发部、运维部、客户成功部。周宁任产品部负责人；陈远任研发部负责人；李卓任运维部负责人。\\n\\n二、执行规则与证据要点\\n\\n产品部提出需求；研发部负责开发；运维部负责部署；客户成功部负责验收沟通。\\n\\n三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\\n\\n四、验证问题\\n\\n请概括企业组织架构_2026Q4的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 485, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 195, \"chunk_type\": \"HEADING\", \"token_count\": 179, \"content_hash\": \"11b9cd8935035f4997485519940536e6ac27187d1a9042b1f9199575799ecb1a\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"公司业务人员关系知识库