INSERT INTO `t_index_outbox` VALUES (2682,'dcf9eeff-b302-4fed-a266-4dc155bc742e','DOCUMENT_STANDARD:82:1',9,'DOCUMENT','KB:9:STANDARD:82','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"岗位职责与协作矩阵 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 44, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 23, \"content_hash\": \"a25ae28bbf8cf0016b8842ace8116d3d98c9a079f597f1e9e7d707ff0623a0ee\", \"heading_path\": \"岗位职责与协作矩阵 V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"文档编号: 文档类型；ROLE-001: 岗位说明\\n文档编号: 数据分类；ROLE-001: 04_公司业务人员关系知识库\\n文档编号: 密级；ROLE-001: 内部受控\\n文档编号: 发布日期；ROLE-001: 2026-10-12\\n文档编号: 数据属性；ROLE-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 199, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 46, \"chunk_type\": \"TABLE\", \"token_count\": 70, \"content_hash\": \"216a84e9a2b9a826114e98b10b520212aa10421122fd33056a8b7a6211c8c177\", \"heading_path\": \"岗位职责与协作矩阵 V1.0\", \"overlap_prefix\": \"岗位职责与协作矩阵 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"一、适用范围与核心内容\\n\\n项目经理周宁负责星河项目计划与验收；技术负责人陈远负责架构与交付；运维负责人李卓负责部署与变更。\\n\\n二、执行规则与证据要点\\n\\n跨部门变更须项目经理协调，生产操作须运维负责人审批。\\n\\n三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\\n\\n四、验证问题\\n\\n请概括岗位职责与协作矩阵_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 473, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 201, \"chunk_type\": \"HEADING\", \"token_count\": 171, \"content_hash\": \"205221dc0f462b7533900faac5a4f3a15d129e530b4dc543ba0c07ee4c9849ca\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"务人员关系知识库\\n文档编号: 密级；