INSERT INTO `t_index_outbox` VALUES (2707,'381ad79a-e189-4059-a8fe-4b4dac001f6c','DOCUMENT_STANDARD:83:1',9,'DOCUMENT','KB:9:STANDARD:83','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"员工信息访问分级规范 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 45, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 24, \"content_hash\": \"3f6361c217328ffeca6859307633b3738dec55d8bc2dab100ca75a6b241fbfe0\", \"heading_path\": \"员工信息访问分级规范 V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"文档编号: 文档类型；ACL-EMP-001: 权限规范\\n文档编号: 数据分类；ACL-EMP-001: 04_公司业务人员关系知识库\\n文档编号: 密级；ACL-EMP-001: 内部受控\\n文档编号: 发布日期；ACL-EMP-001: 2026-10-12\\n文档编号: 数据属性；ACL-EMP-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 215, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 47, \"chunk_type\": \"TABLE\", \"token_count\": 74, \"content_hash\": \"5373245df6d6bdbce4c0391a6c4f836e21dc4b516b3f443cb4e45a182655b3b2\", \"heading_path\": \"员工信息访问分级规范 V1.0\", \"overlap_prefix\": \"员工信息访问分级规范 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"一、适用范围与核心内容\\n\\n组织架构和公开岗位职责为内部公开；员工联系方式、绩效、身份证件属于敏感数据，仅授权HR可查看。\\n\\n二、执行规则与证据要点\\n\\n图谱实体关联不能绕过源文档ACL；跨文档检索结果应按调用者权限过滤。\\n\\n三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\\n\\n四、验证问题\\n\\n请概括员工信息访问分级规范_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 497, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 217, \"chunk_type\": \"HEADING\", \"token_count\": 173, \"content_hash\": \"c63ae28b39b6232cb86348ca3978570fc096333575a5c9b81f00dcca51b33aac\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefi