INSERT INTO `t_index_outbox` VALUES (2716,'d778043e-874d-48de-a1c0-8ee47e1b09a7','CARD_CREATE:K_f162454e855b42a1a4eaaa675eb98cb0:1',9,'CARD','KB:9:CARD:K_f162454e855b42a1a4eaaa675eb98cb0','KNOWLEDGE_OBJECT_UPSERT',1,'/ai/index/knowledge','{\"cards\": [{\"type\": \"PROCEDURE\", \"title\": \"一、适用范围与核心内容\", \"status\": \"DRAFT\", \"content\": \"一、适用范围与核心内容\\n\\n组织架构和公开岗位职责为内部公开；员工联系方式、绩效、身份证件属于敏感数据，仅授权HR可查看。\\n\\n二、执行规则与证据要点\\n\\n图谱实体关联不能绕过源文档ACL；跨文档检索结果应按调用者权限过滤。\\n\\n三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\\n\\n四、验证问题\\n\\n请概括员工信息访问分级规范_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"summary\": \"一、适用范围与核心内容\\n\\n组织架构和公开岗位职责为内部公开；员工联系方式、绩效、身份证件属于敏感数据，仅授权HR可查看。\\n\\n二、执行规则与证据要点\\n\\n图谱实体关联不能绕过源文档ACL；跨文档检索结果应按调用者权限过滤。\\n\\n三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\\n\\n四、验证问题\\n\\n请概括员工信息访问分级规范_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文\", \"confidence\": 0.68, \"updated_at\": \"2026-10-17 10:29:53\", \"entity_codes\": [\"V1.0\", \"一、适用范围与核心内容\", \"HR\", \"ACL\", \"身份证件\", \"引用时\"], \"evidence_ids\": [\"EVD_3a349f9bada84f319619b0fdc43f0805\"], \"evidence_code\": \"EVD_ffff1724de4741c4a7ead11db245a9e4\", \"evidence_hash\": \"3f6361c217328ffeca6859307633b3738dec55d8bc2dab100ca75a6b241fbfe0\", \"evidence_count\": 3, \"knowledge_code\": \"K_f162454e855b42a1a4eaaa675eb98cb0\", \"authority_score\": 0.8, \"permission_tags\": \"[]\"}], \"claims\": [], \"eventId\": \"d778043e-874d-48de-a1c0-8ee47e1b09a7\", \"entities\": null, \"relations\": null, \"indexVersion\": 1, \"knowledgeBaseId\": 9}','SUCCEEDED',1,8,'2026-10-17 10:29:53',NULL,NULL,NULL,'{\"graph\": {\"provider\": \"neo4j\", \"available\": true, \"edgesCreated\": 0, \"nodesCreated\": 1}, \"total\": 58, \"indexed\": 1, \"external\": {\"milvus\": {\"indexed\": 1, \"provider\": \"milvus\"}, \"elasticsearch\": {\"indexed\": 1, \"provider\": \"elasticsearch\"}}, \"graphView\": 71}','2026-10-17 10:29:53','2026-10-17 10:29: