INSERT INTO `t_index_outbox` VALUES (2722,'eb400962-8fde-44a4-9327-a34cba05cf9c','DOCUMENT_STANDARD:84:1',10,'DOCUMENT','KB:10:STANDARD:84','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"软件资产与组件清单 202610\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；ASSET-001: 资产清单\\n文档编号: 数据分类；ASSET-001: 05_漏洞库知识库\\n文档编号: 密级；ASSET-001: 内部\\n文档编号: 发布日期；ASSET-001: 2026-10-12\\n文档编号: 数据属性；ASSET-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 199, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 90, \"content_hash\": \"43004054de85e2cbe8998c89ef77180ad4e97bc882d0254b5b16f4b9b74b4344\", \"heading_path\": \"软件资产与组件清单 202610\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n资产A-SEARCH-01运行atlas-search 2.4.0并启用debug端点；资产A-SEARCH-02运行2.4.1且禁用debug端点。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 289, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 201, \"chunk_type\": \"HEADING\", \"token_count\": 35, \"content_hash\": \"17ad2b94f04b5ba91b7bb9f38af6c369f2041fd413d7345fcf4d2de83d8c0475\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n资产A-SEARCH-01责任人李卓，部署在模拟生产环境；A-SEARCH-02部署在测试环境。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 352, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 291, \"chunk_type\": \"HEADING\", \"token_count\": 30, \"content_hash\": \"a114282259b912fcb7554396572d706b5955f5209c2d775decee8b0604cf766c\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 427, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 354, \"chunk_type\": \"HEADING\", \"token_count\": 47, \"content_hash\": \"cf48e6d73cf9b3cb3b4965927d487a4a8292ac58b3c2f976e6187a25b6987d9b\", \"heading_path\": \"三、数据治理与引用要求\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"四、验证问题\\n\\n请概括软件资产与组件清单_202610的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 524, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 429, \"chunk_type\": \"HEADING\", \"token_count\": 58, \"content_hash\": \"f5ca21b7758d2fa0360dfeb6f65ec8761789309f5c218b7a88958628bcfa9b1a\", \"heading_path\": \"四、验证问题\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}], \"eventId\": \"eb400962-8fde-44a4-9327-a34cba05cf9c\", \"sourceId\": 84, \"standard\": {\"stats\": {\"chars\": 524, \"units\": 5, \"blocks\": 13, \"tables\": 1, \"tokens\": 260, \"sections\": 5, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"STRUCTURE\", \"chunkSize\": 900, \"parentChild\": false, \"chunkOverlap\": 120, \"minChunkSize\": 120, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"STRUCTURE\"}, \"title\": \"软件资产与组件清单 202610\", \"doc_id\": \"e3ae4f920a09486577649a035591047a\", \"sha256\": \"69178096a86efc1894e50b2a4837d9f2b186bfedb0e131e86c39972828fd0afe\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"DOCX\"}, \"sourceUri\": \"upload://02_软件资产与组件清单_202610.docx\", \"documentId\": 84, \"sourceName\": \"02_软件资产与组件清单_202610.docx\", \"indexVersion\": 1, \"permissionTags\": \"[]\", \"knowledgeBaseId\": 10}','SUCCEEDED',1,8,'2026-10-17 10:58:55',NULL,NULL,NULL,'{\"units\": 5, \"documentId\": 84, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 5}, \"knowledgeBaseId\": 10}','2026-10-17 10:58:55','2026-10-17 10:58:57','2026-10-17