INSERT INTO `t_index_outbox` VALUES (2724,'e89f727b-0734-42df-a63f-17aac0407cd6','DOCUMENT_STANDARD:85:1',10,'DOCUMENT','KB:10:STANDARD:85','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"模拟漏洞修复与缓解方案 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；FIX-001: 修复方案\\n文档编号: 数据分类；FIX-001: 05_漏洞库知识库\\n文档编号: 密级；FIX-001: 内部\\n文档编号: 发布日期；FIX-001: 2026-10-12\\n文档编号: 数据属性；FIX-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 189, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 89, \"content_hash\": \"e315eb0693bcc267df05a7b5e018b3197d9af16a143c1529cd58f37e230787b3\", \"heading_path\": \"模拟漏洞修复与缓解方案 V1.0\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n针对KB-2026-001，先关闭debug端点并限制网络访问，再将atlas-search升级到模拟修复版本2.4.1。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 265, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 191, \"chunk_type\": \"HEADING\", \"token_count\": 34, \"content_hash\": \"66cdda872a4b957e5ea5aee771080bf62487a205e0614e5ed4c9097df194b354\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n修复前备份配置，完成变更审批；升级后验证权限控制和查询可用性。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 311, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 267, \"chunk_type\": \"HEADING\", \"token_count\": 28, \"content_hash\": \"3a2cb2ca8796cb762c4cddaa62347321885d2cc8e5ad92d87c1c7b790ba2f0ad\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 386, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 313, \"chunk_type\": \"HEADING\", \"token_count\": 47, \"content_hash\": \"cf48e6d73cf9b3cb3b4965927d487a4a8292ac58b3c2f976e6187a25b6987d9b\", \"heading_path\": \"三、数据治理与引用要求\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"四、验证问题\\n\\n请概括模拟漏洞修复与缓解方案_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 483, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 388, \"chunk_type\": \"HEADING\", \"token_count\": 58, \"content_hash\": \"017158a5ca870a537ae424caa863dfc01863ca5f5740af99fbb63e008400f4d4\", \"heading_path\": \"四、验证问题\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}], \"eventId\": \"e89f727b-0734-42df-a63f-17aac0407cd6\", \"sourceId\": 85, \"standard\": {\"stats\": {\"chars\": 483, \"units\": 5, \"blocks\": 13, \"tables\": 1, \"tokens\": 256, \"sections\": 5, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"STRUCTURE\", \"chunkSize\": 900, \"parentChild\": false, \"chunkOverlap\": 120, \"minChunkSize\": 120, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"STRUCTURE\"}, \"title\": \"模拟漏洞修复与缓解方案 V1.0\", \"doc_id\": \"15c6d4cbdd27abca39ac27479afdc5ba\", \"sha256\": \"0c5931a8844aa4f48f88f7b701afdb49c59d362bb09b6013b5c7f92ad3f17625\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"DOCX\"}, \"sourceUri\": \"upload://03_模拟漏洞修复与缓解方案_V1.0.docx\", \"documentId\": 85, \"sourceName\": \"03_模拟漏洞修复与缓解方案_V1.0.docx\", \"indexVersion\": 1, \"permissionTags\": \"[]\", \"knowledgeBaseId\": 10}','SUCCEEDED',1,8,'2026-10-17 10:58:55',NULL,NULL,NULL,'{\"units\": 5, \"documentId\": 85, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 5}, \"knowledgeBaseId\": 10}','2026-10-17 10:58:55','2026-10-17 10:58:58','2026-10-17 10:58:58');
