INSERT INTO `t_index_outbox` VALUES (2750,'1a2e0fab-362c-4227-9b7d-563a34f23475','DOCUMENT_STANDARD:87:1',10,'DOCUMENT','KB:10:STANDARD:87','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"漏洞复测报告 20261012\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；TEST-001: 复测报告\\n文档编号: 数据分类；TEST-001: 05_漏洞库知识库\\n文档编号: 密级；TEST-001: 内部\\n文档编号: 发布日期；TEST-001: 2026-10-12\\n文档编号: 数据属性；TEST-001: 合成测试数据，非真实企业资料\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 193, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 87, \"content_hash\": \"1efb69682887e42b3e30462030a8299663c79bf1f95f4c3f29776fb94eb6542b\", \"heading_path\": \"漏洞复测报告 20261012\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"一、适用范围与核心内容\\n\\n2026-10-12模拟复测：A-SEARCH-01已升级至2.4.1，debug端点关闭，未授权访问用例返回403。\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 267, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 195, \"chunk_type\": \"HEADING\", \"token_count\": 32, \"content_hash\": \"5b24df913791b5d686b7c0eb33e5a86a82c5b0a0bf37deb54a8648b557a1e2c5\", \"heading_path\": \"一、适用范围与核心内容\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、执行规则与证据要点\\n\\n复测结论：该资产风险已缓解；需持续检查新资产是否使用旧版本。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 312, \"page_end\": null, \"strategy\": \"STRUCTURE\", \"block_type\": \"HEADING\", \"char_start\": 269, \"chunk_type\": \"HEADING\", \"token_count\": 27, \"content_hash\": \"b1a9280141a397e13c2ea83e05d76658ec0852c555f235e8d650969413bc44d1\", \"heading_path\": \"二、执行规则与证据要点\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 387, \"page_end\": null, \"strategy\": \"STRUCTURE\