INSERT INTO `t_task_run` VALUES (89,'TASK309d1427348a4b2e8d1b89dc501f091d',8,'INGESTION','文档接入：01_采购审批管理制度_V1.0.docx','DOCUMENT',NULL,'SUCCEEDED','COMPLETED',100,'MANUAL','admin',0,3,'{\"documentId\": null, \"knowledgeBaseId\": 8}','{\"index\": {\"status\": \"PENDING\", \"eventId\": \"7200c115-4c57-478d-aae3-abbc5a24effb\", \"version\": 1, \"accepted\": true, \"duplicate\": false, \"aggregateKey\": \"KB:8:DOCUMENT:77\"}, \"runId\": 78, \"status\": \"READY\", \"runCode\": \"ING_755b524c74dd44e793a8a1507e9ab29b\", \"filename\": \"01_采购审批管理制度_V1.0.docx\", \"sourceId\": 77, \"standard\": {\"docId\": \"8574899a2bebbc87873bb94e09e47157\", \"stats\": {\"chars\": 498, \"units\": 5, \"blocks\": 13, \"tables\": 1, \"tokens\": 261, \"sections\": 5, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"STRUCTURE\", \"chunkSize\": 1100, \"parentChild\": true, \"chunkOverlap\": 150, \"minChunkSize\": 120, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"STRUCTURE\"}, \"title\": \"采购审批管理制度 V1.0\", \"language\": \"zh\", \"pageCount\": 0, \"sourceFormat\": \"DOCX\"}, \"knowledge\": {\"cards\": [{\"type\": \"FACT\", \"title\": \"采购审批管理制度 V1.0\", \"content\": \"采购审批管理制度 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；POL-PROC-001: 制度\\n文档编号: 数据分类；POL-PROC-001: 03_制度条款知识库\\n文档编号: 密级；POL-PROC-001: 内部\\n文档编号: 发布日期；POL-PROC-001: 2026-10-12\\n文档编号: 数据属性；POL-PROC-001: 合成测试数据，非真实企业资料\", \"summary\": \"采购审批管理制度 V1.0\\n\\n企业知识库验证数据集 | 虚构业务资料 | 版本 1.0\\n\\n文档编号: 文档类型；POL-PROC-001: 制度\\n文档编号: 数据分类；POL-PROC-001: 03_制度条款知识库\\n文档编号: 密级；POL-PROC-001: 内部\\n文档编号: 发布日期；POL-PROC-001: 2026-10-12\\n文档编号: 数据属性；POL-PROC-001: 合成测试数据，非真实企业资料\", \"confidence\": 0.68, \"entity_codes\": [\"采购审批管理制度 V1.0\", \"V1.0\", \"POL-PROC-001\", \"企业知识库\", \"制度条款知识库\"], \"evidence_ids\": [\"EVD_a30c413a475e4e5e932fff412a233e35\"], \"knowledge_code\": \"K_9f4bf0b87f1a43ada645c50ce97f4cef\"}, {\"type\": \"FACT\", \"title\": \"一、适用范围与核心内容\", \"content\": \"一、适用范围与核心内容\\n\\n采购金额不超过50000元由部门负责人审批；超过50000元由部门负责人及财务负责人共同审批。2026-01-01生效。\", \"summary\": \"一、适用范围与核心内容\\n\\n采购金额不超过50000元由部门负责人审批；超过50000元由部门负责人及财务负责人共同审批。2026-01-01生效。\", \"confidence\": 0.68, \"entity_codes\": [\"一、适用范围与核心内容\"], \"evidence_ids\": [\"EVD_fef2ed8aff4442b8aa416f175347bed3\"], \"knowledge_code\": \"K_cfb040ebb1f14de7b22579034eef8fa9\"}, {\"type\": \"FACT\", \"title\": \"二、执行规则与证据要点\", \"content\": \"二、执行规则与证据要点\\n\\n合同签署前须完成供应商资质审查；所有审批记录保留至少三年。\", \"summary\": \"二、执行规则与证据要点\\n\\n合同签署前须完成供应商资质审查；所有审批记录保留至少三年。\", \"confidence\": 0.68, \"entity_codes\": [\"二、执行规则与证据要点\"], \"evidence_ids\": [\"EVD_1510006781e64b74b1436a5bd2ecad15\"], \"knowledge_code\": \"K_64117add6a204ae4b356c8cbb3330216\"}, {\"type\": \"RULE\", \"title\": \"三、数据治理与引用要求\", \"content\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"summary\": \"三、数据治理与引用要求\\n\\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\", \"confidence\": 0.68, \"entity_codes\": [\"三、数据治理与引用要求\", \"引用时\"], \"evidence_ids\": [\"EVD_f6aa01e4a1d24611b8427a1087b7ae0c\"], \"knowledge_code\": \"K_d179e333c7be4d5db202bcc020f65c3a\"}, {\"type\": \"PROCEDURE\", \"title\": \"四、验证问题\", \"content\": \"四、验证问题\\n\\n请概括采购审批管理制度_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"summary\": \"四、验证问题\\n\\n请概括采购审批管理制度_V1.0的关键要求并提供来源引用。\\n\\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\\n\\n如果文件内容与其他版本冲突，应该如何裁决？\", \"confidence\": 0.68, \"entity_codes\": [\"V1.0\", \"四、验证问题\"], \"evidence_ids\": [\"EVD_20def2d7752d4859b7ba54130f9acc92\"], \"knowledge_code\": \"K_8e007452a235402c832ed2cdedcdb88f\"}], \"claims\": [{\"object\": \"采购审批管理制度 V1.0\", \"subject\": \"采购审批管理制度 V1.0\", \"predicate\": \"流程\", \"claim_code\": \"CLM_c71b121fbae74cbdbd861c276c8e8f0e\", \"conditions\": [], \"confidence\": 0.62, \"derivation\": \"FALLBACK\", \"entity_codes\": [\"采购审批管理制度 V1.0\", \"V1.0\"], \"evidence_ids\": [\"EVD_a30c413a475e4e5e932fff412a233e35\"]}, {\"object\": \"一、适用范围与核心内容\", \"subject\": \"一、适用范围与核心内容\",