INSERT INTO `t_content_unit` VALUES (605,69,'CU_02f99b2967ce48deab358a07e15016fa',NULL,'一、适用范围与核心内容','HEADING',NULL,NULL,200,492,180,'ACTIVE','[]',1,1,'一、适用范围与核心内容\n\n星河项目建设企业搜索平台，交付范围包括知识采集、混合检索、问答溯源及权限审计。计划2026年11月完成试运行。\n\n二、执行规则与证据要点\n\n项目负责人周宁；技术负责人陈远；验收依据为检索准确率、引用覆盖率及越权访问测试。\n\n三、数据治理与引用要求\n\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\n\n四、验证问题\n\n请概括项目星河交付说明_V1.0的关键要求并提供来源引用。\n\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\n\n如果文件内容与其他版本冲突，应该如何裁决？','3d402fabc960cdea9d74be4b3d761593230444ba81fbc041aec453bf8ce6fe58','2026-10-17 09:13:10');
