INSERT INTO `t_content_unit` VALUES (618,73,'CU_aa12b940debc45c7b83aca7c3d7cd002',NULL,'一、适用范围与核心内容','HEADING',NULL,NULL,206,272,38,'ACTIVE','[]',1,1,'一、适用范围与核心内容\n\n现象：接口延迟增加，连接池active达到上限，等待线程持续增长。先检查慢SQL、未释放连接和连接池配置。','62029a21971dcdcdb36ee0d96e0b93786179519b24d680193ecbb1d9651dc790','2026-10-17 09:28:54');
INSERT INTO `t_content_unit` VALUES (619,73,'CU_fdc52248270149e192332b97773276a3',NULL,'二、执行规则与证据要点','HEADING',NULL,NULL,274,344,40,'ACTIVE','[]',1,1,'二、执行规则与证据要点\n\n步骤：1.采集监控与日志；2.检查数据库活跃连接；3.隔离异常请求；4.必要时经审批调整连接池；5.记录恢复时间。','0b1f59cac0880cee48122df64343a9e9d96feac6e25efd4ac1bcb58e6a56fdd7','2026-10-17 09:28:54');
