INSERT INTO `t_content_unit` VALUES (649,79,'CU_58d9bde5893244839be09d216b5cb0d5',NULL,'二、执行规则与证据要点','HEADING',NULL,NULL,281,328,30,'ACTIVE','[]',1,1,'二、执行规则与证据要点\n\n裁决依据：新版生效日期及明确替代条款；历史采购按发生时有效版本核验。','09708705632a8fbedb5aa3a8b13ebcd9d2a9973fc608f2d29d66a2e6cc67e31a','2026-10-17 09:59:25');
