INSERT INTO `t_content_unit` VALUES (654,80,'CU_c9b8ddc710b64e2482082487395d331d',NULL,'一、适用范围与核心内容','HEADING',NULL,NULL,195,485,179,'ACTIVE','[]',1,1,'一、适用范围与核心内容\n\n星云科技（虚构）设产品部、研发部、运维部、客户成功部。周宁任产品部负责人；陈远任研发部负责人；李卓任运维部负责人。\n\n二、执行规则与证据要点\n\n产品部提出需求；研发部负责开发；运维部负责部署；客户成功部负责验收沟通。\n\n三、数据治理与引用要求\n\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\n\n四、验证问题\n\n请概括企业组织架构_2026Q4的关键要求并提供来源引用。\n\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\n\n如果文件内容与其他版本冲突，应该如何裁决？','11b9cd8935035f4997485519940536e6ac27187d1a9042b1f9199575799ecb1a','2026-10-17 10:28:55');
