INSERT INTO `t_content_unit` VALUES (657,81,'CU_12714fd013ed4652af4870cc75a8744e',NULL,'一、适用范围与核心内容','HEADING',NULL,NULL,198,471,171,'ACTIVE','[]',1,1,'一、适用范围与核心内容\n\n星河项目由星云科技交付给北辰制造（虚构客户）。客户联系人王岚负责需求确认与验收签字。\n\n二、执行规则与证据要点\n\n项目经理周宁向客户联系人王岚汇报里程碑；陈远对接客户技术团队。\n\n三、数据治理与引用要求\n\n引用时必须标记文档编号、版本和原文位置。发生冲突时，优先核验生效日期、适用范围和审批记录；不得以生成式回答替代权威文档。\n\n四、验证问题\n\n请概括星河项目客户与交付关系_V1.0的关键要求并提供来源引用。\n\n将本文件与同一知识库其他文件关联，列出相关实体、规则和证据。\n\n如果文件内容与其他版本冲突，应该如何裁决？','4076859c22f3598eb540c4265f11be9de4c4c891a1b1590ab27eebb0ae6b015b','2026-10-17 10:28:55');
